// FdOffer.java — a limited FD offer row with a lock flag to simulate row locking
package com.nbi.db;

import java.util.concurrent.locks.ReentrantLock;

public class FdOffer {
    final String id;
    int unitsRemaining;
    final ReentrantLock rowLock = new ReentrantLock(); // stands in for InnoDB row lock

    public FdOffer(String id, int unitsRemaining) {
        this.id = id; this.unitsRemaining = unitsRemaining;
    }
}
