// AllotmentService.java — plain read (unsafe) vs locking read (safe)
package com.nbi.db;

public class AllotmentService {

    // UNSAFE: plain SELECT then check then update — race between read and write.
    public boolean allotPlainRead(FdOffer offer) {
        int remaining = offer.unitsRemaining;   // plain read (snapshot)
        simulateThinkTime();                     // window where another txn can act
        if (remaining >= 1) {                    // verify
            offer.unitsRemaining = remaining - 1;// decrement (may overwrite)
            return true;
        }
        return false;
    }

    // SAFE: SELECT ... FOR UPDATE — lock row until "commit", serialize critical section.
    public boolean allotLockingRead(FdOffer offer) {
        offer.rowLock.lock();                    // SELECT ... FOR UPDATE (acquire row lock)
        try {
            int remaining = offer.unitsRemaining;// locked read
            simulateThinkTime();                 // even with delay, others are blocked
            if (remaining >= 1) {                // verify
                offer.unitsRemaining = remaining - 1; // decrement
                return true;
            }
            return false;
        } finally {
            offer.rowLock.unlock();              // COMMIT/ROLLBACK releases the lock
        }
    }

    private void simulateThinkTime() {
        try { Thread.sleep(20); } catch (InterruptedException ignored) {}
    }
}
