// Demo.java — two concurrent allotments on a 1-unit offer, both paths
package com.nbi.db;

import java.util.concurrent.*;

public class Demo {
    public static void main(String[] args) throws Exception {
        AllotmentService svc = new AllotmentService();

        // --- Plain read: likely oversubscribes (both succeed) ---
        FdOffer plain = new FdOffer("FD-PLAIN", 1);
        runTwo(() -> svc.allotPlainRead(plain), "PLAIN read");
        System.out.println("  PLAIN  unitsRemaining = " + plain.unitsRemaining
                + (plain.unitsRemaining < 0 ? "  <- OVERSUBSCRIBED!" : ""));

        // --- Locking read: second allotment correctly rejected ---
        FdOffer locked = new FdOffer("FD-LOCK", 1);
        runTwo(() -> svc.allotLockingRead(locked), "LOCKING read (FOR UPDATE)");
        System.out.println("  LOCKED unitsRemaining = " + locked.unitsRemaining
                + "  <- correct, exactly one allotted");
    }

    private static void runTwo(Callable<Boolean> task, String label) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        Future<Boolean> f1 = pool.submit(task);
        Future<Boolean> f2 = pool.submit(task);
        boolean r1 = f1.get(), r2 = f2.get();
        pool.shutdown();
        System.out.println(label + ": allot1=" + r1 + " allot2=" + r2
                + (r1 && r2 ? "  (BOTH succeeded!)" : "  (only one succeeded)"));
    }
}
